    Bug 1925248 - Wait for content page load (and use a real page) in messageDisplayScript tests. r=tobyp

    We use `awaitBrowserLoaded()` in almost all other cases when loading a content
    page. The screenshot [1] of a recent test fail shows the page still loading when
    the error occurs. Let's wait for the load here as well (and let's use a real
    content page instead of just http://mochi.test:8888/).

    [1]: https://firefoxci.taskcluster-artifacts.net/YhdqE7QyTS24rtWN3y799Q/0/public/test_info/mozilla-test-fail-screenshot_7i8qoxo4.png

    Differential Revision: https://phabricator.services.mozilla.com/D276229

diff --git a/mail/components/extensions/test/browser/browser_ext_messageDisplayScripts.js b/mail/components/extensions/test/browser/browser_ext_messageDisplayScripts.js
index e8dbdac92f8..06fcd7b11a8 100644
--- a/mail/components/extensions/test/browser/browser_ext_messageDisplayScripts.js
+++ b/mail/components/extensions/test/browser/browser_ext_messageDisplayScripts.js
@@ -4,6 +4,9 @@

 "use strict";

+const CONTENT_PAGE =
+  "http://mochi.test:8888/browser/comm/mail/components/extensions/test/browser/data/content.html";
+
 let gAccount, gMessages;
 let gDefaultTabmail, gDefaultAbout3Pane, gDefaultMessagePane;

@@ -648,7 +651,8 @@ add_task(async function testRegister() {
   await testDonePromise;

   // Open a content tab. The CSS and script shouldn't apply.
-  const contentTab = window.openContentTab("http://mochi.test:8888/");
+  const contentTab = window.openContentTab(CONTENT_PAGE);
+  await awaitBrowserLoaded(contentTab.browser, CONTENT_PAGE);
   // Let's wait a while and see if anything happens:
   // eslint-disable-next-line mozilla/no-arbitrary-setTimeout
   await new Promise(resolve => setTimeout(resolve, 1000));
@@ -1045,7 +1049,8 @@ add_task(async function testRunAt() {
   // Open a content tab. The message display scripts should not be injected.
   // If they DO get injected, we will end up with 3 additional messages from the
   // extension and the test will fail.
-  const contentTab = window.openContentTab("http://mochi.test:8888/");
+  const contentTab = window.openContentTab(CONTENT_PAGE);
+  await awaitBrowserLoaded(contentTab.browser, CONTENT_PAGE);
   Assert.equal(gDefaultTabmail.tabInfo.length, 3);
   // eslint-disable-next-line mozilla/no-arbitrary-setTimeout
   await new Promise(resolve => setTimeout(resolve, 1000));
